from pybricks.hubs import PrimeHub
from pybricks.parameters import Direction, Port, Stop
from pybricks.pupdevices import Motor
from pybricks.robotics import DriveBase

# Set up.
left_gear_ = Motor(Port.C, Direction.CLOCKWISE)
right_gear_ = Motor(Port.D, Direction.CLOCKWISE)
prime_hub = PrimeHub()
my_69 = Motor(Port.E, Direction.CLOCKWISE)
my_41 = Motor(Port.A, Direction.COUNTERCLOCKWISE)
drive_baaaaaaase = DriveBase(my_41, my_69, 62.4, 128)


# The main program starts here.
drive_baaaaaaase.use_gyro(True)
drive_baaaaaaase.straight(290)
drive_baaaaaaase.settings(straight_speed=200)
right_gear_.run_angle(500, 300)
left_gear_.run_angle(500, -550)
drive_baaaaaaase.straight(-100)
drive_baaaaaaase.settings(straight_speed=400)
right_gear_.run_angle(500, -300)
drive_baaaaaaase.straight(-300)
left_gear_.run_angle(500, 550)
